ValidationRule.errorConditionFormula:
AND( RecordType.DeveloperName = 'Sales_Offers_Request', NOT ( $UserRole.Id = $Label.QF_Support_QIC_Member), /*QF-Support-Agency Support-QAC*/ CONTAINS( $User.Level__c, "SO(SME)"), CONTAINS( $User.Level__c, "SO(SPS)"),
OR ( ISPICKVAL ( Type , "Bespoke Incentive"), ISPICKVAL ( Type , "Survey") )
)
